// EDIT ME: replace these three example URLs with your real public pages.
// One item is returned per URL so each page is fetched, chunked and
// embedded separately. Add or remove lines as needed.
const URLS = [
  'https://yourbusiness.example/faq',
  'https://yourbusiness.example/pricing',
  'https://yourbusiness.example/policies'
];
return URLS.map(url => ({ json: { url } }));

// Strip scripts/styles/HTML, normalise whitespace, then split into
// ~1200-character chunks with 200 characters of overlap so a fact that
// sits on a boundary still appears whole in at least one chunk.
const out = [];
for (const item of $input.all()) {
  const url = item.json.url;
  let html = '';
  if (typeof item.json.data === 'string') html = item.json.data;
  else if (typeof item.json.body === 'string') html = item.json.body;
  else if (item.json.data) html = JSON.stringify(item.json.data);
  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
  const SIZE = 1200, OVERLAP = 200;
  let i = 0, idx = 0;
  while (i < text.length) {
    const chunk = text.slice(i, i + SIZE).trim();
    if (chunk) out.push({ json: { url: url, chunk_index: idx++, content: chunk } });
    if (i + SIZE >= text.length) break;
    i += SIZE - OVERLAP;
  }
}
return out;

