// Combine the retrieved chunks into one context block for the AI.
// Handles the common vector-store response shapes: an array of rows
// (as separate items, or under .data / .result), or a single row.
const items = $input.all();
let rows = [];
if (items.length > 1) {
  rows = items.map(i => i.json);
} else {
  const d = items[0].json;
  if (Array.isArray(d)) rows = d;
  else if (Array.isArray(d.data)) rows = d.data;
  else if (Array.isArray(d.result)) rows = d.result;
  else if (d.content) rows = [d];
}
const chunks = rows.slice(0, 4);
const context_text = chunks.map((r, i) => '[' + (i + 1) + '] ' + (r.content || r.page_content || '')).join('\n\n');
const sources = [...new Set(chunks.map(r => r.source_url || r.url || '').filter(Boolean))];
const question = $('Normalise Question').first().json.question;
return [{ json: { question: question, context_text: context_text, sources: sources } }];

