// Safely parse the AI's JSON reply and return exactly what the website
// widget needs: { answer, sources }. Any parse failure falls back to
// the safe fallback message rather than leaking raw model output.
const raw = ($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '';
let answer = '';
try { answer = (JSON.parse(raw).answer || '').trim(); } catch (e) { answer = ''; }
if (!answer) answer = 'I don\'t have that in our published information — please WhatsApp us…';
const sources = $('Build Answer Prompt').first().json.sources || [];
return [{ json: { answer: answer, sources: sources } }];
